var mult = 0.0;
var lvlscale = 1.0;
const rank = GetNpcEliteRank(GetOwner()); 

if(rank == 0){
    set mult = 0.005;
}
else if(rank == 1){
    set mult = 0.015;
}
else if(rank == 2){
    set mult = 0.04;
}
else if(rank >= 3){
    set mult = 0.08;
}

if(GetNPCLevel() <= 10){
    set lvlscale = 1.0;
}
else if(GetNPCLevel() >= 11 && GetNPCLevel() <= 19){
    set lvlscale = 2.0;
}
else if(GetNPCLevel() >= 20){
    set lvlscale = 7.0;
}


mult / lvlscale
